"0600\"\n    content: |\n      REPLACE_ME_DUCKDNS_TOKEN\nruncmd:\n  - |\n    set -u\n    export HOME=/root\n    export LUMA_UNATTENDED=1\n    export LUMA_DUCKDNS_TOKEN_FILE=/etc/luma/duckdns-token\n    INSTALLER_URL=\"https://REPLACE_ME_CENTER_HOST/install.sh\"\n    (\n      case \"$INSTALLER_URL\" in\n        *REPLACE_ME*) echo \"Setup stopped: the installer URL still holds a REPLACE_ME value. Fill the installer URL in the cloud-init file, then create the server again.\"; exit 1 ;;\n      esac\n      if grep -q REPLACE_ME /etc/luma/install.env; then\n        echo \"Setup stopped: /etc/luma/install.env still holds a REPLACE_ME value. Fill every REPLACE_ME value in install.env in the cloud-init file, then create the server again.\"\n        exit 1\n      fi\n      set -a\n      . /etc/luma/install.env\n      set +a\n      curl --fail --silent --show-error --location --proto '=https' --tlsv1.2 \\\n        --output /root/luma-install.sh \"$INSTALLER_URL\" || exit 1\n      bash /root/luma-install.sh\n    ) >> /var/log/luma-install.log 2>&1\n    status=$?\n    # The installer shreds the token file itself. This removes it when the installer stopped before reading it.\n    shred --iterations=1 --zero --remove=unlink /etc/luma/duckdns-token 2>/dev/null || true\n    exit \"$status\"\n";
